section2.example:
{
  "manifestSpecVersion": "0",
  "agent": {
    "jid": "weather@agents.example",
    "name": "weather",
    "title": "Weather Agent",
    "description": "Provides weather forecasts.",
    "version": "1.4.0",
    "vendor": "Example"
  },
  "implementation": {"name":"example-weather","version":"3.2.1"},
  "mcpProtocolVersion": "2025-11-25",
  "tools": [{
    "name": "forecast.get",
    "title": "Get Forecast",
    "description": "Gets a forecast for one city.",
    "inputSchema": {
      "type": "object",
      "properties": { "city": { "type": "string" } },
      "required": ["city"],
      "additionalProperties": false
    },
    "outputSchema": {
      "type": "object",
      "properties": { "summary": { "type": "string" } },
      "required": ["summary"]
    },
    "annotations": {
      "readOnlyHint": true,
      "destructiveHint": false,
      "idempotentHint": true,
      "openWorldHint": true
    },
    "execution": {"taskSupport":"optional"},
    "urn:xmpp:agent-api:0": {
      "supportsProgress": true,
      "supportsCancellation": true,
      "defaultTimeoutSeconds": 30,
      "maximumTimeoutSeconds": 120,
      "requiredPermissions": ["weather.read"],
      "approvalRequired": false,
      "tags": ["weather", "forecast"]
    }
  }]
}

section1.code:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:xmpp:agent-task:0:event-json",
  "$defs": {
    "status": {
      "type": "object",
      "required": ["state", "updatedAt"],
      "properties": {
        "state": {"enum":["running","input_required","cancelling"]},
        "updatedAt": {"type":"string","format":"date-time"}
      },
      "additionalProperties": false
    },
    "progress": {
      "type": "object",
      "minProperties": 1,
      "properties": {
        "percent": {"type":"number","minimum":0,"maximum":100},
        "stage": {"type":"string","maxLength":256},
        "message": {"type":"string","maxLength":4096}
      },
      "additionalProperties": false
    },
    "input_required": {
      "type": "object",
      "required": ["requestId", "question", "inputSchema", "createdAt"],
      "properties": {
        "requestId": {
          "type":"string",
          "pattern":"^[A-Za-z0-9._~-]{22,128}$"
        },
        "question": {"type":"string","minLength":1,"maxLength":4096},
        "inputSchema": {"type":"object"},
        "createdAt": {"type":"string","format":"date-time"},
        "expiresAt": {"type":"string","format":"date-time"}
      },
      "additionalProperties": false
    },
    "toolResult": {
      "type": "object",
      "required": ["content"],
      "properties": {
        "content": {"type":"array","items":{"type":"object"}},
        "structuredContent": {},
        "isError": {"type":"boolean"},
        "_meta": {"type":"object"}
      },
      "additionalProperties": false
    },
    "completed": {
      "type": "object",
      "required": ["result"],
      "properties": {
        "result": {"$ref":"#/$defs/toolResult"},
        "summary": {"type":"string","maxLength":4096}
      },
      "additionalProperties": false
    },
    "failed": {
      "type": "object",
      "required": ["error"],
      "properties": {
        "error": {
          "type":"object",
          "required":["code","message","retryable"],
          "properties":{
            "code":{"type":"string","pattern":"^[A-Za-z0-9_.:-]{1,128}$"},
            "message":{"type":"string","minLength":1,"maxLength":4096},
            "retryable":{"type":"boolean"},
            "details":{"type":"object"}
          },
          "additionalProperties":false
        }
      },
      "additionalProperties": false
    },
    "cancelled": {
      "type": "object",
      "properties": {
        "reason": {"type":"string","maxLength":4096}
      },
      "additionalProperties": false
    }
  }
}
